import React from "react";
import { styled } from "@mui/material/styles";
import Button from "@mui/material/Button";
import PlayArrowIcon from "@mui/icons-material/PlayArrow";

import { PALETTE, PLAYER_STATUS, PLAYTIME_PHASE } from "../constants";
import Timer from "./Timer";

const { LOGIN, EXPLORE, KEEPGOING } = PLAYTIME_PHASE;
const PLAYTIME_PHASE_BG_COLORS = {
  [EXPLORE]: "rgba(33, 33, 33, 0.25)",
  [KEEPGOING]: "rgba(33, 33, 33, 0.8)",
};

const { PLAYING, PAUSED } = PLAYER_STATUS;

const LOGIN_INSTRUCTION = `Help your students customize and confirm their characters.`;
const PLAYTIME_INSTRUCTIONS = {
  [LOGIN]: {
    [PLAYING]: LOGIN_INSTRUCTION,
    [PAUSED]: LOGIN_INSTRUCTION,
  },
  [EXPLORE]: {
    [PLAYING]:
      "TIP:\nClick on the book icon to check block definitions and object names.",
    [PAUSED]: `Hey teacher, here's your chance to try the puzzle too!\n\nPress "Start Teacher Play" and use your arrow keys to move.`,
  },
  [KEEPGOING]: {
    [PLAYING]:
      "TIP:\nPress 'Z' as a shortcut to undo\n\nPress 'R' as a shortcut to reset",
    [PAUSED]:
      "Now's a good chance to walk around and see how your students are doing!",
  },
};

const GAME_URL = `https://9dots.gitlab.io/next-gen-pre-production/biycr/play/`;

const Gameplay = ({
  gameRef,
  playtimePhase,
  gameplayRoute,
  isGamePlaying,
  setIsGamePlaying,
  timerTimes,
  setDisableArrowControls,
  handleNavigation,
  nextSlideLabel,
  openTimerModal,
  setOpenTimerModal,
}) => {
  const handlePlayBtnClick = () => {
    if (gameRef.current) {
      setIsGamePlaying(true);
      gameRef.current.contentWindow.focus();
    }
  };

  return (
    <div id="gameplay">
      <div id="gameplay-container">
        <iframe
          ref={gameRef}
          id="game"
          key={playtimePhase}
          title="Game Play"
          scrolling="no"
          tabIndex={-1}
          onLoad={() => {
            /**
             * checking isGamePlaying is necessary since user can press play
             * button before game iframe loads in which case it should have
             * focus over one-click
             */
            if (!isGamePlaying) {
              window.focus();
            }
          }}
          src={`${GAME_URL}${gameplayRoute}`}
        />
        {!isGamePlaying && (
          <GamePaused
            handlePlayBtnClick={handlePlayBtnClick}
            playtimePhase={playtimePhase}
          />
        )}
        <div className="column">
          <Timer
            type="game"
            key={playtimePhase}
            phase={playtimePhase}
            timerTimes={timerTimes}
            setDisableArrowControls={setDisableArrowControls}
            handleNavigation={handleNavigation}
            nextSlideLabel={nextSlideLabel}
            openTimerModal={openTimerModal}
            setOpenTimerModal={setOpenTimerModal}
            isGamePlaying={isGamePlaying}
            setIsGamePlaying={setIsGamePlaying}
          />
          <Instructions
            playtimePhase={playtimePhase}
            isGamePlaying={isGamePlaying}
          />
        </div>
      </div>
    </div>
  );
};

export default Gameplay;

const GamePaused = ({ handlePlayBtnClick, playtimePhase }) => {
  const StyledButton = styled(Button)(() => ({
    alignSelf: "center",
    width: "350px",
    height: "64px",
    fontFamily: "Roboto Mono",
    fontWeight: "bold",
    fontSize: "24px",
    textTransform: "capitalize",
    color: PALETTE.green,
    backgroundColor: "#212121b3", // opacity 0.7
    "&:hover": {
      backgroundColor: PALETTE.green,
      color: PALETTE.black,
    },
  }));
  return (
    <div
      id="game-paused"
      style={{ backgroundColor: PLAYTIME_PHASE_BG_COLORS[playtimePhase] }}
    >
      <StyledButton
        onClick={handlePlayBtnClick}
        startIcon={<PlayArrowIcon style={{ width: "30px", height: "30px" }} />}
      >
        Start Teacher Play
      </StyledButton>
    </div>
  );
};

const Instructions = ({ playtimePhase, isGamePlaying }) => {
  const text =
    PLAYTIME_INSTRUCTIONS[playtimePhase]?.[isGamePlaying ? PLAYING : PAUSED];
  return (
    <div id="game-instructions">
      <span>{text}</span>
    </div>
  );
};
