import React, { useEffect, useState } from "react";

import Modal from "@mui/material/Modal";
import Button from "@mui/material/Button";
import Fade from "@mui/material/Fade";
import PlayArrowIcon from "@mui/icons-material/PlayArrow";
import { ThemeProvider } from "@mui/material/styles";
import {
  PLAYTIME_PHASE,
  GREEN_THEME,
  DISCUSS_PHASE,
  TIMER_MODAL_SUBPHASE,
  SLIDE_ADDITIONAL_INFO,
} from "../constants";

const { LOGIN, EXPLORE, KEEPGOING } = PLAYTIME_PHASE;
const { DISCUSS_PARTNER, DISCUSS_CLASS } = DISCUSS_PHASE;
const { START, END, END_EARLY } = TIMER_MODAL_SUBPHASE;

const START_PLAY_DEFAULT_TEXT = {
  header: "Let's Play!",
  continueBtn: "Start",
};
const END_DEFAULT_TEXT = {
  header: "Time's Up!",
  continueBtn: "Continue",
};
const END_EARLY_DEFAULT_TEXT = {
  header: "End Timer Early?",
  subheader: "You still have some time left...",
  continueBtn: "Continue",
  backBtn: "Back",
};
const MODAL_TEXT = {
  [LOGIN]: {
    [START]: {
      header: "Let's Login!",
      continueBtn: "Start",
    },
    [END]: END_DEFAULT_TEXT,
    [END_EARLY]: END_EARLY_DEFAULT_TEXT,
  },
  [EXPLORE]: {
    [START]: START_PLAY_DEFAULT_TEXT,
    [END]: {
      header: "Poll Time!",
      subheader: "Time's up! It's time to vote...",
      continueBtn: "Go to Poll",
    },
    [END_EARLY]: {
      ...END_EARLY_DEFAULT_TEXT,
      continueBtn: "Go to Poll",
    },
  },
  [KEEPGOING]: {
    [START]: START_PLAY_DEFAULT_TEXT,
    [END]: {
      header: "Time's Up!",
      continueBtn: "Continue Story",
    },
    [END_EARLY]: {
      ...END_EARLY_DEFAULT_TEXT,
      continueBtn: "Continue Story",
    },
  },
  [DISCUSS_PARTNER]: {
    [START]: {
      header: "Talk to a Partner",
      continueBtn: "Start",
    },
    [END]: END_DEFAULT_TEXT,
    [END_EARLY]: END_EARLY_DEFAULT_TEXT,
  },
  [DISCUSS_CLASS]: {
    [START]: {
      header: "Share as a class!",
      continueBtn: "Start",
    },
    [END]: {
      header: "Poll Results!",
      subheader: "Time to see the results!",
      continueBtn: "See Results",
    },
    [END_EARLY]: END_EARLY_DEFAULT_TEXT,
  },
};
const DEFAULT_TIMEOUT = 500;

const TimerModal = ({
  open,
  handleClose,
  phase,
  subphase,
  time,
  nextSlideLabel,
  continueDisabled,
}) => {
  const [displaySubphase, setDisplaySubphase] = useState(subphase);
  const [wasOpen, setWasOpen] = useState(open);
  useEffect(() => {
    if (open !== wasOpen) {
      setWasOpen(open);
      if (open) {
        setDisplaySubphase(subphase);
      }
    }
  }, [displaySubphase, open, subphase, wasOpen]);

  const { header, subheader, continueBtn } = getTexts(
    phase,
    displaySubphase,
    nextSlideLabel
  );

  const isEndEarly = displaySubphase === END_EARLY;
  const isStart = displaySubphase === START;

  const timeoutMultiplier = continueDisabled ? 3 : 1;

  return (
    <Modal disableRestoreFocus open={open} onClose={handleClose} disablePortal>
      <Fade in={open} timeout={DEFAULT_TIMEOUT * timeoutMultiplier}>
        <div id="timer-modal">
          <div id="timer-modal-header">{header}</div>
          {subheader && <div id="timer-modal-subheader">{subheader}</div>}
          <div id="timer-modal-timer-text">{time}</div>
          <div id="timer-modal-buttons-container">
            <ThemeProvider theme={GREEN_THEME}>
              {isEndEarly && (
                <Button
                  id="timer-modal-back-btn"
                  onClick={handleClose}
                  variant="contained"
                >
                  Close
                </Button>
              )}
              <Button
                id={`timer-modal-continue-btn${isEndEarly ? "-endearly" : ""}`}
                onClick={handleClose}
                variant="contained"
                disabled={continueDisabled}
                sx={{
                  filter: continueDisabled
                    ? "grayscale(1) brightness(80%)"
                    : "none",
                  transition: "filter 0.3s ease-in-out",
                }}
              >
                {isStart && (
                  <PlayArrowIcon
                    sx={{ fontSize: "46px", marginRight: "16px " }}
                  />
                )}
                {continueBtn}
                {!isStart && (
                  <PlayArrowIcon
                    sx={{ fontSize: "30px", marginLeft: "16px" }}
                  />
                )}
              </Button>
            </ThemeProvider>
          </div>
        </div>
      </Fade>
    </Modal>
  );
};

export default TimerModal;

function getTexts(phase, subphase, nextSlideLabel) {
  if (
    phase === EXPLORE &&
    subphase !== START &&
    nextSlideLabel !== SLIDE_ADDITIONAL_INFO.polltime.label
  ) {
    // use text with continue story for subphase end (early)
    return MODAL_TEXT[KEEPGOING][subphase];
  } else {
    return MODAL_TEXT[phase][subphase];
  }
}
