export const GLOSSARY_TAB_KEYS = {
  BLOCKS: "blocks",
  OBJECTS: "objects",
  CHARACTERS: "characters",
};

export const TAB_SECTION_KEYS = {
  [GLOSSARY_TAB_KEYS.BLOCKS]: {
    states: "states",
    connectors: "connectors",
  },
};

const PROCESS_DATA_FUNCS = {
  // filters data and modifies thingsToConsider info data depending on lesson number
  [GLOSSARY_TAB_KEYS.BLOCKS]: (data, { lessonNum }) =>
    data
      .filter(({ showLessonNum }) => showLessonNum <= lessonNum)
      .map(
        ({
          info: { thingsToConsider, thingsToConsiderAfterLesson, ...otherInfo },
          ...otherItemData
        }) => ({
          ...otherItemData,
          info: {
            ...otherInfo,
            thingsToConsider: [
              ...thingsToConsider,
              ...(thingsToConsiderAfterLesson
                ? Array.from(Array(lessonNum + 1).keys()).reduce(
                    (arr, lessonNumKey) => {
                      const additionalThingsToConsider =
                        thingsToConsiderAfterLesson?.[lessonNumKey];
                      if (additionalThingsToConsider) {
                        arr.push(...additionalThingsToConsider);
                      }
                      return arr;
                    },
                    []
                  )
                : []),
            ],
          },
        })
      )
      .sort(sortItemsAlphabetically),
  // filters data depending on current lesson number
  [GLOSSARY_TAB_KEYS.OBJECTS]: (data, { lessonNum }) =>
    data
      .filter(({ appearsInLesson }) => appearsInLesson[lessonNum])
      .sort(sortItemsAlphabetically),
  // filters data depending on current lesson number
  [GLOSSARY_TAB_KEYS.CHARACTERS]: (data, { lessonNum }) =>
    data.filter(
      ({ showInfo, hideInfo }) =>
        showInfo.lessonNum <= lessonNum &&
        (!hideInfo || lessonNum < hideInfo.lessonNum)
    ),
};

