import { useEffect } from "react";
import { Stack } from "@mui/material";
import { ThemeProvider } from "@mui/material/styles";
import Button from "@mui/material/Button";
import LeftIcon from "@mui/icons-material/KeyboardArrowLeft";
import RightIcon from "@mui/icons-material/KeyboardArrowRight";
import FullscreenIcon from "@mui/icons-material/Fullscreen";
import FullscreenExitIcon from "@mui/icons-material/FullscreenExit";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import PauseIcon from "@mui/icons-material/Pause";
import PollIcon from "@mui/icons-material/Poll";
import GlossaryIcon from "@mui/icons-material/AutoStoriesOutlined";
import { PLAYER_STATUS, GREEN_THEME, PALETTE } from "../constants";
import SlideProgress from "./SlideProgress";

const PLAYER_STATUS_ICON_DATA = {
  [PLAYER_STATUS.POLLING]: { IconComponent: PollIcon, color: "#69b8e3" },
  [PLAYER_STATUS.PAUSED]: { IconComponent: PauseIcon, color: "#FB923C" },
  [PLAYER_STATUS.PLAYING]: {
    IconComponent: AccountCircleIcon,
    color: "#22C55E",
  },
};

const Controls = ({
  disableArrowControls,
  setSlideChangeInfo,
  ctrlBarData,
  numOfSlides,
  isFullscreen,
  isShowingGlossary,
  handleFullscreenToggle,
  handleGlossaryToggle,
  playerStatus,
  slideSections,
  slidesMarks,
  slideNumsToHideSlideDisplay,
  thumbnailImages,
  isGamePlaying,
  setIsGamePlaying,
  shouldHideSlideDisplay,
  handleNavigation,
  setOpenTimerModal,
}) => {
  // clickers emulates Page/Arrow key presses
  useEffect(() => {
    function keyDownListener(e) {
      if (disableArrowControls) {
        return;
      }
      if (isShowingGlossary) return;
      if (["PageUp", "ArrowUp", "ArrowLeft"].includes(e.key)) {
        handleNavigation("prev");
      } else if (["PageDown", "ArrowDown", "ArrowRight"].includes(e.key)) {
        handleNavigation("next");
      }
    }

    document.addEventListener("keydown", keyDownListener);

    return () => {
      document.removeEventListener("keydown", keyDownListener);
    };
  }, [handleNavigation, disableArrowControls, isShowingGlossary]);

  const handleNavigationWrapper = (dir) => {
    // arrow keys are disabled on slides with timers and navigation
    // with control left and right buttons are disabled too and should
    // open end early timer modal
    if (disableArrowControls) {
      setOpenTimerModal(true);
    } else {
      handleNavigation(dir);
    }
  };

  return (
    <div
      className="slides-controls"
      style={{
        backgroundColor: isGamePlaying ? PALETTE.darkGreen : PALETTE.black,
      }}
    >
      {!!slideSections.length && (
        <Stack
          direction="column"
          justifyContent="flex-start"
          alignItems="center"
          height="100%"
        >
          <SlideProgress
            sections={slideSections}
            currSlideInfo={ctrlBarData.curr}
            numOfSlides={numOfSlides}
            slidesMarks={slidesMarks}
            setSlideChangeInfo={setSlideChangeInfo}
            slideNumsToHideSlideDisplay={slideNumsToHideSlideDisplay}
            thumbnailImages={thumbnailImages}
            isGamePlaying={isGamePlaying}
            shouldHideSlideDisplay={shouldHideSlideDisplay}
          />
          <div className="ctrl-bar-outer-container ">
            <div className="ctrl-bar-inner-container ">
              {isGamePlaying && (
                <PauseGameButton setIsGamePlaying={setIsGamePlaying} />
              )}
              <div className={`ctrl-bar-center ${isGamePlaying ? "hide" : ""}`}>
                <SlideNavButton
                  Icon={LeftIcon}
                  disabled={ctrlBarData.curr.slideNumber === 1}
                  onClick={() => handleNavigationWrapper("prev")}
                />
                <div className="ctrl-bar-text">
                  <p>{`${ctrlBarData.curr.slideNumber} / ${numOfSlides}`}</p>
                </div>
                <SlideNavButton
                  Icon={RightIcon}
                  disabled={ctrlBarData.curr.slideNumber === numOfSlides}
                  onClick={() => handleNavigationWrapper("next")}
                />
              </div>
              <div className="ctrl-bar-right">
                <div className="ctrl-bar-player-status-container">
                  <PlayerStatusIcon playerStatus={playerStatus} />
                  <div className="ctrl-bar-text">
                    <p>Students {playerStatus}</p>
                  </div>
                </div>
                <div className="ctrl-bar-divider" />
                {/** @todo show book icon button if playtimePhase is truthy */}
                <ToggleGlossaryButton
                  tabIndex={0}
                  onClick={handleGlossaryToggle}
                  onKeyDown={({ key }) => {
                    if (key === "Enter") {
                      handleGlossaryToggle();
                    }
                  }}
                />
                <ToggleFullscreenButton
                  Icon={isFullscreen ? FullscreenExitIcon : FullscreenIcon}
                  tabIndex={0}
                  onClick={handleFullscreenToggle}
                  onKeyDown={({ key }) => {
                    if (key === "Enter") {
                      handleFullscreenToggle();
                    }
                  }}
                />
              </div>
            </div>
          </div>
        </Stack>
      )}
    </div>
  );
};

const ToggleGlossaryButton = (props) => {
  return (
    <div className="ctrl-bar-btn-container ctrl-bar-responsive-icon">
      <CtrlBarIconButton {...props} Icon={GlossaryIcon} />
    </div>
  );
};

/** @todo fix button icon to display correct icon when using hotkey F11 to toggle fullscreen? */
const ToggleFullscreenButton = (props) => {
  return (
    <div className="ctrl-bar-btn-container ctrl-bar-responsive-icon">
      <CtrlBarIconButton {...props} />
    </div>
  );
};

const PlayerStatusIcon = ({ playerStatus }) => {
  const { IconComponent, color } = PLAYER_STATUS_ICON_DATA[playerStatus];

  return (
    <div className="ctrl-bar-player-status-icon ctrl-bar-responsive-icon">
      <IconComponent
        fontSize="inherit"
        sx={{
          color,
        }}
      />
    </div>
  );
};

const SlideNavButton = (props) => (
  <div className="ctrl-bar-responsive-icon">
    <CtrlBarIconButton {...props} />
  </div>
);

const CtrlBarIconButton = ({ Icon, onClick, ...otherProps }) => (
  <Icon
    className="ctrl-bar-icon-btn"
    fontSize="inherit"
    onClick={(e) => {
      e.currentTarget.blur();
      onClick();
    }}
    {...otherProps}
  />
);

const PauseGameButton = ({ setIsGamePlaying }) => (
  /** @todo create mui green theme wrapper? green color same as play button in Gameplay */
  <ThemeProvider theme={GREEN_THEME}>
    <Button
      id="game-pause-btn"
      onClick={() => setIsGamePlaying(false)}
      variant="outlined"
      startIcon={<PauseIcon />}
    >
      Pause Teacher Play
    </Button>
  </ThemeProvider>
);
export default Controls;
