import { countBy, mapValues, transform } from "lodash";
import { useEffect, useMemo, useState } from "react";

import { getDocSnapshot, updateFirestoreDoc } from "../firebase";
import { playlistData } from "../playlistData";
import { PLAYER_STATUS } from "../constants";

const useSessionData = (sessionId, thisRemoteUuid) => {
  const [sessionData, setSessionData] = useState({});
  const [pollResults, setPollResults] = useState({});

  useEffect(() => {
    updateFirestoreDoc("sessions", sessionId, { remoteUuid: thisRemoteUuid });
    return getDocSnapshot("sessions", sessionId, (snapshot) => {
      setSessionData(snapshot.data());
    });
  }, [sessionId, thisRemoteUuid]);

  /** @todo update identifier isClassPause to better represent its value, boolean or string (discuss slide id) */
  const {
    isClassPause,
    lessonId = null,
    sessionPolls: sessionPollsId,
    pollId,
    remoteUuid,
  } = sessionData;

  const pollsData = useMemo(
    () => playlistData?.[lessonId]?.data?.polls ?? {},
    [lessonId]
  );

  useEffect(() => {
    if (sessionPollsId) {
      const unsubscribe = getDocSnapshot(
        "sessionPolls",
        sessionPollsId,
        (snapshot) => {
          const { results = {} } = snapshot.data();
          setPollResults(
            mapValues(results, (pollQuestionObj, pollId) => {
              const maybePollData = pollsData[pollId];

              // if the poll id from the online database does not match local poll data
              // (presumably due to online database corruption),
              // do not process that set of results
              if (!maybePollData) {
                return [];
              }

              const { choices, correctChoiceId } = maybePollData;
              const noPollResponses = transform(
                choices,
                (acc, val) => {
                  acc[val.choiceId] = 0;
                },
                {}
              );

              return transform(
                {
                  ...noPollResponses,
                  ...countBy(Object.values(pollQuestionObj)),
                },
                (questionData, votes, choiceId) => {
                  questionData.push({
                    choiceId,
                    votes,
                    choiceText: choices[Number(choiceId) - 1].text,
                    correct: choiceId === correctChoiceId,
                  });
                },
                []
              );
            })
          );
        }
      );

      return unsubscribe;
    } else {
      setPollResults({});
    }
  }, [pollsData, sessionPollsId]);

  const pollsNumCompleted = mapValues(pollResults, (pollResult) =>
    pollResult.reduce((acc, curr) => acc + curr.votes, 0)
  );

  // note: current poll data is omitted because it's managed locally and not by the database
  return {
    hasRemoteControl: thisRemoteUuid === (remoteUuid ?? thisRemoteUuid), // assume we have remote if remote remote id is not yet set
    isClassPause,
    lessonId,
    pollQuestions: mapValues(pollsData, "question"),
    pollResults,
    sessionPollsId,
    playerStatus: pollId
      ? PLAYER_STATUS.POLLING
      : isClassPause
      ? PLAYER_STATUS.PAUSED
      : PLAYER_STATUS.PLAYING,
    currPollNumCompleted: pollId ? pollsNumCompleted[pollId] : null,
  };
};

export default useSessionData;
