import React from "react";
import SlideDisplay from "./SlideDisplay";
import PollResults from "./PollResults";
import Gameplay from "./Gameplay";

const MainView = ({
  hideSlideDisplay,
  pollQuestion,
  pollResults,
  slideUrl,
  handleSlidePostMessage,
  currPollNumCompleted,
  gameRef,
  playtimePhase,
  discussPhase,
  gameplayRoute,
  isGamePlaying,
  setIsGamePlaying,
  timerTimes,
  setDisableArrowControls,
  handleNavigation,
  nextSlideLabel,
  openTimerModal,
  setOpenTimerModal,
}) => {
  return (
    <div id="main-view">
      <SlideDisplay
        isHidden={hideSlideDisplay}
        slideUrl={slideUrl}
        handleSlidePostMessage={handleSlidePostMessage}
        currPollNumCompleted={currPollNumCompleted}
        discussPhase={discussPhase}
        timerTimes={timerTimes}
        setDisableArrowControls={setDisableArrowControls}
        handleNavigation={handleNavigation}
        openTimerModal={openTimerModal}
        setOpenTimerModal={setOpenTimerModal}
        setIsGamePlaying={setIsGamePlaying}
      />
      {pollResults && (
        <PollResults question={pollQuestion} results={pollResults} />
      )}
      {playtimePhase && (
        <Gameplay
          gameRef={gameRef}
          playtimePhase={playtimePhase}
          gameplayRoute={gameplayRoute}
          isGamePlaying={isGamePlaying}
          setIsGamePlaying={setIsGamePlaying}
          timerTimes={timerTimes}
          setDisableArrowControls={setDisableArrowControls}
          handleNavigation={handleNavigation}
          nextSlideLabel={nextSlideLabel}
          openTimerModal={openTimerModal}
          setOpenTimerModal={setOpenTimerModal}
        />
      )}
    </div>
  );
};

export default MainView;
