import React, { useState, useEffect, useCallback } from "react";
import dayjs from "dayjs";

import IconButton from "@mui/material/IconButton";
import PauseIcon from "@mui/icons-material/Pause";
import PlayArrowIcon from "@mui/icons-material/PlayArrow";
import ReplayIcon from "@mui/icons-material/Replay";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { TimeField } from "@mui/x-date-pickers/TimeField";

import {
  PALETTE,
  PLAYTIME_PHASE,
  DISCUSS_PHASE,
  TIMER_MODAL_SUBPHASE,
  isNavKey,
} from "../constants";
import TimerModal from "./TimerModal";

const SECONDS_IN_MINUTE = 60;
const { LOGIN, EXPLORE, KEEPGOING } = PLAYTIME_PHASE;
const { DISCUSS_PARTNER, DISCUSS_CLASS } = DISCUSS_PHASE;
const DEFAULT_TIMES_BY_PHASE = {
  [LOGIN]: 3,
  [EXPLORE]: 4,
  [DISCUSS_PARTNER]: 2,
  [DISCUSS_CLASS]: 3,
  [KEEPGOING]: 26,
};

const DEFAULT_ICON_FONT_SIZE = "24px";
const ICON_BUTTON_BG_COLOR = "#616161";

const { START, END, END_EARLY } = TIMER_MODAL_SUBPHASE;

// used to disable input when transitioning from active gameplay to end timer modal
const KEYDOWN_DISABLED_DURATION = 2000;

// editing states
const IS_EDITING = "IS_EDITING";
const CANCEL_EDIT_QUEUED = "CANCEL_EDIT_QUEUED";
const CONFIRM_EDIT_QUEUED = "CONFIRM_EDIT_QUEUED";

// timer times and default times are in minutes and logic to determine time remaining is in seconds
const Timer = ({
  timerTimes = {},
  phase,
  type,
  setDisableArrowControls,
  handleNavigation,
  nextSlideLabel,
  openTimerModal,
  setOpenTimerModal,
  isGamePlaying,
  setIsGamePlaying,
}) => {
  const defaultTimerDuration =
    (timerTimes[phase] ?? DEFAULT_TIMES_BY_PHASE[phase]) * SECONDS_IN_MINUTE;

  const [hasStarted, setHasStarted] = useState(false);
  const [isPaused, setIsPaused] = useState(true);

  const [timerDuration, setTimerDuration] = useState(defaultTimerDuration);
  const [timeRemaining, setTimeRemaining] = useState(timerDuration);

  const [disableKeydown, setDisableKeydown] = useState(false);

  const [editingState, setEditingState] = useState(null);
  useEffect(() => {
    if (editingState === CANCEL_EDIT_QUEUED) {
      setIsPaused(false);
      setEditingState(null);
    } else if (editingState === CONFIRM_EDIT_QUEUED) {
      setTimeRemaining(timerDuration);
      setIsPaused(false);
      setEditingState(null);
    }
  }, [editingState, timerDuration]);

  // effect; editingState truthy, but not actively editing--set things and resume play

  const modalSubphase = !hasStarted ? START : !timeRemaining ? END : END_EARLY;

  const handleTogglePlay = () => {
    if (!timeRemaining) {
      return;
    }
    setIsPaused(!isPaused);
  };

  const handleReset = () => {
    setIsPaused(false);
    setTimeRemaining(defaultTimerDuration);
  };

  const handleFocus = () => {
    setIsGamePlaying(false);
    setTimerDuration(timeRemaining);
    setIsPaused(true);
    setEditingState(IS_EDITING);
  };

  const handleBlur = () => {
    setEditingState((state) =>
      state === CANCEL_EDIT_QUEUED ? CANCEL_EDIT_QUEUED : CONFIRM_EDIT_QUEUED
    );
  };

  const handleChange = (value) => {
    if (value?.isValid()) {
      setTimerDuration(value.unix());
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Escape") {
      setEditingState(CANCEL_EDIT_QUEUED);
      e.target.blur();
    } else if (e.key === "Enter") {
      e.target.blur();
    } else if (e.key === "Tab") {
      // manually editing the selection seems to mess with the internal <TimeField /> logic =\
      /* //
      const { selectionStart, selectionEnd } = e.target;
      if (selectionStart <= 2 && selectionEnd <= 2) {
        e.target.setSelectionRange(3, 5);
      } else if (selectionStart >= 3 && selectionEnd >= 3) {
        e.target.setSelectionRange(0, 2);
      }
      // */

      // prevent moving to next input
      e.preventDefault();
    }
    e.stopPropagation();
  };

  const handleCloseModal = useCallback(
    (e) => {
      if (disableKeydown) {
        return;
      }

      const isPrevNavKey = isNavKey("prev", e.key);
      const isNextNavKey = isNavKey("next", e.key);

      if (e.key && !isPrevNavKey && !isNextNavKey && e.key !== "Escape") {
        return;
      }

      setHasStarted(true);
      setIsPaused(false);
      setOpenTimerModal(false);

      if (isPrevNavKey) {
        handleNavigation("prev");
      } else if (
        modalSubphase === END ||
        (modalSubphase === END_EARLY &&
          (isNextNavKey || e.target.id === "timer-modal-continue-btn-endearly"))
      ) {
        handleNavigation("next");
      }
    },
    [handleNavigation, modalSubphase, setOpenTimerModal, disableKeydown]
  );

  const handleEarlyNavigation = useCallback(
    (e) => {
      if (editingState) {
        return;
      }

      if (
        modalSubphase === END_EARLY &&
        (isNavKey("prev", e.key) || isNavKey("next", e.key))
      ) {
        setOpenTimerModal(true);
        setIsPaused(true);
      }
    },
    [modalSubphase, setOpenTimerModal, editingState]
  );

  useEffect(() => {
    const timerInterval = setInterval(() => {
      if (isPaused || !timeRemaining) {
        return;
      }
      setTimeRemaining((prevTime) => {
        if (prevTime === 0) {
          return 0;
        } else {
          return prevTime - 1;
        }
      });
    }, 1000);

    return () => clearInterval(timerInterval);
  }, [isPaused, timeRemaining]);

  useEffect(() => {
    if (modalSubphase === END) {
      setOpenTimerModal(true);
      setTimeout(
        () => setDisableKeydown(false),
        isGamePlaying ? KEYDOWN_DISABLED_DURATION : 0
      );
      if (isGamePlaying) {
        setDisableKeydown(true);
        window.focus(); // take focus away from game to capture keydown
      }
    }
  }, [modalSubphase, setOpenTimerModal, isGamePlaying, setDisableKeydown]);

  // setOpenTimerModal can be called by <Controls />
  useEffect(() => {
    if (openTimerModal) {
      setIsPaused(true);
    }
  }, [openTimerModal]);

  // disable arrow controls on mount and re-enable arrow controls on unmount
  useEffect(() => {
    setDisableArrowControls(true);
    setOpenTimerModal(true);
    return () => {
      setDisableArrowControls(false);
      setOpenTimerModal(false);
    };
  }, [setDisableArrowControls, setOpenTimerModal]);

  useEffect(() => {
    const timerKeydownListener = (e) => {
      if (openTimerModal) {
        handleCloseModal(e);
      } else {
        handleEarlyNavigation(e);
      }
    };

    document.addEventListener("keydown", timerKeydownListener);

    return () => {
      document.removeEventListener("keydown", timerKeydownListener);
    };
  }, [openTimerModal, handleCloseModal, handleEarlyNavigation]);

  return (
    <div id={`timer-${type}`}>
      {type === "discuss" && (
        <TogglePlay isPaused={isPaused} handleTogglePlay={handleTogglePlay} />
      )}
      <LocalizationProvider dateAdapter={AdapterDayjs}>
        <TimeField
          id="mmss"
          name="mmss"
          value={dayjs.unix(editingState ? timerDuration : timeRemaining)}
          /** @todo figure out "m:ss" format for non-keepgoing sections */
          format="mm:ss"
          onFocus={handleFocus}
          onBlur={handleBlur}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          variant="standard"
          InputProps={{
            disableUnderline: true,
            style: {
              maxWidth: "inherit",
              maxHeight: "inherit",
              color: "inherit",
              fontFamily: "inherit",
              fontWeight: "inherit",
              fontSize: "inherit",
            },
          }}
        />
      </LocalizationProvider>
      {type === "discuss" && <Reset handleReset={handleReset} />}
      <hr
        className="time-underline"
        style={{
          visibility: editingState ? "visible" : "hidden",
          width: type === "game" ? "195px" : "20cqh",
        }}
      />
      {type === "game" && (
        <TimerControlsGame
          phase={phase}
          isPaused={isPaused}
          handleTogglePlay={handleTogglePlay}
          handleReset={handleReset}
          fontSize="36px"
        />
      )}
      <TimerModal
        open={openTimerModal}
        handleClose={handleCloseModal}
        phase={phase}
        subphase={modalSubphase}
        continueDisabled={disableKeydown}
        /** @todo switch "m:ss" when <TimeField /> format figured out */
        time={dayjs.unix(timeRemaining).format("mm:ss")}
        nextSlideLabel={nextSlideLabel}
      />
    </div>
  );
};

export default Timer;

const TimerControlsGame = ({
  isPaused,
  handleTogglePlay,
  handleReset,
  fontSize,
}) => {
  return (
    <div id="timer-game-controls">
      <TogglePlay
        isPaused={isPaused}
        handleTogglePlay={handleTogglePlay}
        fontSize={fontSize}
      />
      <Reset handleReset={handleReset} fontSize={fontSize} />
    </div>
  );
};

const iconButtonStyle = {
  "& .MuiSvgIcon-root": {
    color: PALETTE.gray,
  },
  "&:hover": {
    backgroundColor: ICON_BUTTON_BG_COLOR,
    "& .MuiSvgIcon-root": {
      color: "white",
    },
  },
};

const TogglePlay = ({ isPaused, handleTogglePlay, fontSize }) => {
  const iconStyle = { fontSize: fontSize ?? DEFAULT_ICON_FONT_SIZE };
  return (
    <IconButton
      onClick={handleTogglePlay}
      sx={
        isPaused
          ? {
              "&:hover": {
                backgroundColor: PALETTE.contrastGreen,
              },
              backgroundColor: PALETTE.green,
            }
          : iconButtonStyle
      }
    >
      {isPaused ? (
        <PlayArrowIcon sx={iconStyle} />
      ) : (
        <PauseIcon sx={iconStyle} />
      )}
    </IconButton>
  );
};

const Reset = ({ handleReset, fontSize }) => {
  return (
    <IconButton onClick={handleReset} sx={iconButtonStyle}>
      <ReplayIcon sx={{ fontSize: fontSize ?? DEFAULT_ICON_FONT_SIZE }} />
    </IconButton>
  );
};
